select no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','delete-owner@example.test'),('22222222-2222-4222-8222-222222222222','delete-stranger@example.test');
insert into opportunities(id,user_id,input) values('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','Referral post');
