insert into conversations(id,user_id) values('44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111');
insert into messages(id,user_id,conversation_id,role,content) values('55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111','44444444-4444-4444-8444-444444444444','user','I build Java APIs');
insert into memories(user_id,key,content,evidence,source_message_id,conflict_source_message_id) values('11111111-1111-4111-8111-111111111111','skills.java','Builds Java APIs','I build Java APIs','55555555-5555-4555-8555-555555555555','55555555-5555-4555-8555-555555555555');
insert into research_sources(user_id,opportunity_id,url,title,content) values('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','https://example.test','Role','Research');
select ok(not has_function_privilege('authenticated','delete_opportunity(uuid,uuid)','execute'),'Direct clients cannot delete opportunities');
