update drafts set status='sending';
select throws_ok($$select delete_opportunity('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333')$$,'P0001','Resolve the pending or uncertain email delivery before deleting this opportunity','Sending blocks deletion');
update drafts set status='unknown';
select throws_ok($$select delete_opportunity('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333')$$,'P0001','Resolve the pending or uncertain email delivery before deleting this opportunity','Uncertain delivery blocks deletion');
update drafts set status='draft';
select is(delete_opportunity('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333'),true,'Owner can delete');
select is((select count(*)::int from opportunities),0,'Opportunity removed');
select is((select count(*)::int from drafts),0,'Draft removed');
select is((select count(*)::int from research_sources),0,'Research removed');
select is((select count(*)::int from conversations),0,'Draft conversation removed');
select is((select count(*)::int from messages),0,'Draft messages removed');
select is((select count(*)::int from memories where content='Builds Java APIs' and source_message_id is null and conflict_source_message_id is null),1,'Memory preserved with detached provenance');
select * from finish();
rollback;
